import{_ as e,o as t,c as i,a3 as o}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"Aligning Cyber Space with Physical World: A Comprehensive Survey on Embodied AI","description":"","frontmatter":{"title":"Aligning Cyber Space with Physical World: A Comprehensive Survey on Embodied AI","arxiv":"2407.06886","date":"2024-07-09","authors":"Yang Liu, Weixing Chen, Yongjie Bai, Xiaodan Liang, Guanbin Li, Wen Gao, Liang Lin","categories":"cs.CV, cs.AI, cs.LG, cs.MA, cs.RO","topics":"具身智能综述, 世界模型, 机器人数据集","outline":[2,2]},"headers":[],"relativePath":"papers/2407.06886.md","filePath":"papers/2407.06886.md","lastUpdated":null}'),r={name:"papers/2407.06886.md"};function n(s,a,l,d,p,h){return t(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="aligning-cyber-space-with-physical-world-a-comprehensive-survey-on-embodied-ai" tabindex="-1">Aligning Cyber Space with Physical World: A Comprehensive Survey on Embodied AI <a class="header-anchor" href="#aligning-cyber-space-with-physical-world-a-comprehensive-survey-on-embodied-ai" aria-label="Permalink to &quot;Aligning Cyber Space with Physical World: A Comprehensive Survey on Embodied AI&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2407.06886" target="_blank" rel="noreferrer">2407.06886</a></td></tr><tr><td><strong>提交日期</strong></td><td>2024-07-09</td></tr><tr><td><strong>作者</strong></td><td>Yang Liu, Weixing Chen, Yongjie Bai, Xiaodan Liang, Guanbin Li, Wen Gao, Liang Lin</td></tr><tr><td><strong>分类</strong></td><td>cs.CV, cs.AI, cs.LG, cs.MA, cs.RO</td></tr><tr><td><strong>一句话</strong></td><td>用「AI 大脑 + 身体 + 跨模态传感器」的 ABC 框架把具身智能重组为感知、交互、智能体、sim-to-real 四条主线做系统综述，并给出统一多机器人数据标准 ARIO 与约 300 万 episode 的配套数据集。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/embodied-ai-general">通用具身智能</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本说明</p><p>本文首次提交于 2024-07-09，本页依据 <strong>v8</strong>（2025-08-25 修订）全文撰写。v8 已把 Genesis、NVIDIA Cosmos、InfiniteWorld 等 2025 年出现的工作补入正文，因此内容比 v1 的引用范围宽得多。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>这篇综述要回答的问题不是「某个具身模型怎么做得更好」，而是「2023 年多模态大模型（MLM）爆发之后，具身智能这个领域到底被重新组织成了什么形状」。作者的判断是：MLM 与世界模型（WM）一起把具身智能从「针对某个任务训练某个策略」推到了「用一个通用大模型驱动一个物理实体」，而此前的综述（作者点名 [17, 5, 6, 18]）大多写于 2023 年之前，或只覆盖 VLA 模型、或只覆盖智能制造，无法反映这一转变。</p><p>重要性在于领域的碎片化程度。做仿真器的人、做 VLN 的人、做抓取的人、做 sim-to-real 的人各自有一套基准与术语，而一个真正可用的具身智能体必须同时用到全部四块。作者提出的 ABC 模型（AI brain / Body / Cross-modal sensors）就是为了给这四块一个共同的坐标系：世界模型充当 A，执行与人机交互充当 B，主动多模态感知充当 C。综述另一层价值是把数据这一环从「附录里的一句话」提到了贡献级别 —— 他们直接给出了一个新的数据标准和数据集，而不是只呼吁「需要更多数据」。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>综述本身的对照组是既有综述。作者指出：2023 年之前的具身智能综述以深度强化学习和导航为主体，MLM 尚未成为可选项；2023 年之后仅有的两篇里，一篇聚焦 vision-language-action 模型，一篇聚焦面向智能制造的具身系统（且 ABC 架构最早正是在后者中提出）。它们能做到的是各自领域内的清点，做不到的是把「仿真器 — 感知 — 交互 — 智能体 — sim-to-real」串成一条从 cyber space 到 physical world 的完整链路，也没有把世界模型这一新增部件放进架构里。</p><p>在被综述的对象层面，作者对既有工作的批评是具体的。仿真器方面，AI2-THOR 与 VirtualHome 的交互是脚本式的，缺乏真实物理接触；Habitat 的智能体几乎没有交互能力，只适合导航。数据方面，Open X-Embodiment 看似统一，但（作者列举）没有任何一个数据集同时含图像、3D 视觉、文本、触觉与听觉；多机器人数据格式不统一导致加载与处理成本高；不同平台的控制对象无法互相表示；仿真数据与真实数据很少共存于同一数据集，而这恰恰是研究 sim-to-real 最需要的组合。世界模型方面，作者把已有工作分成生成式、预测式、知识驱动三类，并直言它们在高维感知输入、随机性与长程依赖上都难以泛化。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>顺着 2023–2024 年的既有事实往下推，这条路径并不难还原。第一步是观察到 RT-2、RT-H、PaLM-E 这类工作把互联网预训练的视觉语言模型直接当作机器人策略骨干，效果远好于从零训练的专用策略 —— 这说明「大模型 + 物理实体」已经成为主流配方。第二步是注意到这个配方的短板同样明显：长期记忆、复杂意图理解、复杂任务分解仍然不行，而这三项恰恰是 LLM 端的问题，不是控制端的问题。于是「智能体」自然成为独立的一节。</p><p>第三步来自另一条线索：Sora 类视频生成模型与 Dreamer 类隐空间预测模型在 2024 年前后同时被当作「世界模型」讨论。作者据此推断，机器人真正缺的是一个能在头脑里模拟物理后果的模块，而 LLM 的内部知识不足以承担这个角色 —— 正文里有一句很直接的话：没有具身世界模型的动作规划器无法只靠 LLM 的内部知识模拟物理定律。第四步则是纯工程观察：既然所有路线都撞在数据上，而 Open X-Embodiment 的统一只是形式上的，那么与其再写一段「呼吁社区合作」，不如自己定义一个能容纳异构形态与多模态的记录格式。ARIO 就是这一步的产物。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>具身智能的难点不在于任何单一模块，而在于 cyber space 里学到的表示与 physical world 里的因果结构对不齐：模型能把「番茄」认出来，却不知道抓它需要多大力、放歪了会滚下桌。作者的组织方式是把这条对齐链拆成四个可独立评测的环节（感知、交互、智能体、sim-to-real），并主张世界模型是把前三者黏合起来的那块胶水 —— 因为只有它同时承担「预测下一步会发生什么」和「据此选择做什么」。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>综述的「pipeline」是它的分类骨架，用一个具体任务串起来最清楚：假设指令是「把桌上的杯子放进水槽」。</p><ul><li><strong>仿真器（第 3 节）</strong>：先在何处训练。作者把仿真器分成通用型（Isaac Sim 的高保真物理与实时光追、Gazebo 的 ROS 集成与传感器仿真、PyBullet 的易用性、Genesis 的可微物理与生成能力，共 11 个在表 II 中对比）与真实场景型（SAPIEN 擅长铰接物体，iGibson 提供大规模真实场景，TDW 支持音频与流体，Matterport3D/Habitat 主打导航）。还单列了一类自动场景构建工作：RoboGen 用 LLM 从随机 3D 资产生成任务，HOLODECK 按人类指令在 AI2-THOR 里定制场景，PhyScene 用条件扩散生成物理一致的 3D 场景，ProcTHOR 程序化生成可交互场景。</li><li><strong>具身感知（第 4 节）</strong>：主动视觉感知（vSLAM、3D 场景理解的投影/体素/点式三类方法）与视觉语言导航，负责建立「杯子在哪、水槽在哪、我在哪」。</li><li><strong>具身交互（第 5 节）</strong>：具身问答（EQA，在探索中收集足够信息后停止并作答）与具身抓取，后者已从闭集类别转向开放集、语言引导抓取。</li><li><strong>具身智能体（第 6 节）</strong>：多模态基础模型 + 任务规划。作者区分了分层范式（LLM 做高层规划、调用已训练好的策略模型或函数库，如 Reflexion、DEPS）与端到端范式，并指出分层范式的模块化便于独立开发但引入延迟、且整体效果被外部策略模型质量卡住。</li><li><strong>Sim-to-Real（第 7 节）</strong>：包含世界模型、数据收集与训练、控制算法三块。sim-to-real 范式被归纳为五种：Real2Sim2Real（在数字孪生里用 RL 学策略再迁回）、TRANSIC（实时人工干预 + 残差策略）、域随机化、系统辨识、Lang4sim2real（用自然语言描述做跨域图像表示对齐）。</li><li><strong>ARIO</strong>：统一记录不同形态机器人的控制与运动数据，带精确时间戳，可容纳变长数据；在此标准上构建的数据集含约 300 万 episode、258 个系列、321,064 个任务。</li></ul><p>最后第 8 节列出五个挑战：高质量机器人数据集、长程任务执行、因果推理、统一评测基准、安全与隐私。其中评测那一条的意见值得单独记：作者认为不应只用问答题评高层规划器，而应把高层规划器与低层控制策略放在一起跑长程任务、测成功率。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文无形式化数学推导，跳过。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p>作为综述，本文没有自己的模型实验，主要证据形式是对比表格与分类清单：表 I 对比 disembodied 与 embodied AI，表 II 对比 11 个通用仿真器的关键特性与应用场景，另有针对真实场景仿真器、数据集与各任务代表方法的汇总。第 7 节末尾用图 12 展示 ARIO 的示例任务。</p><p>需要如实说明的是：<strong>ARIO 作为本文唯一的原创贡献，在正文中没有任何配套实验</strong> —— 既没有「在 ARIO 上预训练 vs 在 Open X-Embodiment 上预训练」的对照，也没有报告任何模型在 ARIO 上训练后的下游成功率。约 300 万 episode、258 个系列、321,064 个任务这组规模数字，以及「统一格式便于加载与训练」这一说法，目前只由数据集本身的存在支撑。因此本页不引用任何 ARIO 带来的性能数字（论文里也没有）。</p><p>综述给出的结论性判断有三条比较硬：（a）脚本式交互的仿真器对需要精细接触的任务不够用；（b）没有世界模型的 LLM 规划器无法模拟物理定律，这是 cyber-to-physical 迁移失败的结构性原因；（c）现有世界模型在 sim-to-real 上仍然受限于仿真器无法刻画真实物理与噪声。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：这是一篇以 MLM 与世界模型为中心重写的具身智能综述，用 ABC（AI 大脑 / 身体 / 跨模态传感器）框架统一组织。它把领域拆成机器人本体、仿真器、具身感知、具身交互、具身智能体、sim-to-real 六块，并对每块给出代表工作与失效模式。它对既有综述的批评是它们要么写于 MLM 之前、要么只覆盖单一子问题。原创贡献是 ARIO 数据标准与约 300 万 episode 的统一数据集，用来解决多模态缺失、格式不统一、仿真与真实数据不共存三个问题。但 ARIO 在文中未经任何下游实验验证。</p><p><strong>3 句话版</strong>：MLM + 世界模型让具身智能从「专用策略」走向「通用大脑驱动物理实体」，这篇综述按这条主线重组了整个领域。它给出的最有价值的判断是：数据格式与世界模型是两处真正的结构性瓶颈，而非某个算法不够好。配套的 ARIO 数据标准是对第一处瓶颈的直接回应，但尚无实验证据。</p><p><strong>1 句话版</strong>：一份把具身智能按「感知 — 交互 — 智能体 — sim-to-real」四线重排的 MLM 时代综述，外加一个未经验证的统一多机器人数据标准 ARIO。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一条是：<strong>统一的数据记录格式能带来统一的学习收益</strong>。ARIO 的全部论证建立在「格式不统一是数据难用的主因」之上，但格式只是最表层的障碍；真正让跨机器人预训练变难的是动作语义、控制频率、观测视角与硬件动力学的差异 —— 同样是「夹爪开合」，在不同平台上可能是位置控制、速度控制或力控，时间尺度也差一个量级。把它们写进同一个带时间戳的文件里，并不能自动让梯度往同一个方向走。</p><p>论文为这条假设提供的证据是：现有数据集缺多模态、缺统一格式、缺仿真-真实混合，这些描述性事实是对的。但它缺的证据是任何一次「用 ARIO 训练后在下游任务上更好」的测量。相比之下，同期工作对这个问题给出的是另一种答案 —— 例如 <a href="/notes/papers/2410.07864">RDT-1B</a> 明确设计了一个 128 维「物理可解释统一动作空间」并把每一维绑定到具体物理量，说明业内认为统一的关键在动作语义层而非文件格式层。若 ARIO 的收益主要来自「数据变多」而非「格式变统一」，那么这项贡献就退化为又一次数据聚合。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做、且不需要复现任何模型的验证：取 Open X-Embodiment 中形态差异最大的三个子集（例如单臂 6-DoF、单臂 7-DoF、双臂），分别按 ARIO 标准转写一遍，然后训练两个规模相同的小型行为克隆策略：A 用 ARIO 统一格式（动作按物理量对齐并带 padding 掩码），B 用朴素做法（各机器人独立动作头，或直接零填充且不给掩码）。在同一个留出机器人上评测。</p><ul><li>支持 ARIO 的结果：A 在留出机器人上的成功率显著高于 B，且差距随参与预训练的机器人种类增加而扩大。</li><li>反驳的结果：A 与 B 在误差棒内持平，或差距只来自「A 见到的有效样本更多」（可用等样本量对照排除）。</li></ul><p>这个实验的关键是把「格式统一」与「数据变多」拆开，而这正是综述目前没做的对照。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>站在反对者立场，最有力的攻击是指出综述的中心论断 —— 「没有世界模型的规划器无法模拟物理定律，因此无法完成物理世界任务」 —— 存在一个更省事的替代解释：闭环重规划。设计这样一个对照：在同一批长程操作任务上比较（i）显式世界模型 + 一次性规划、（ii）无世界模型但每 k 步用当前观测重新规划、（iii）无世界模型且开环执行。若（ii）逼近甚至超过（i），那么「必须在头脑里模拟物理」的结论就被削弱为「必须频繁看一眼真实世界」，而后者的工程代价低得多。同期具身工作里已有间接佐证：<a href="/notes/papers/2407.08693">ECoT</a> 的主结果恰恰是把高层推理<strong>冻结 5 步</strong>后成功率不降反升（63% → 72%），说明&quot;每步都重新想一遍&quot;未必是收益来源。</p><p>第二条攻击针对分类学本身：ABC 框架把「世界模型」放在 AI 大脑的位置，但正文里被归为世界模型的方法（生成式视频模型、隐空间预测模型、知识驱动模型）在目标函数上互不兼容 —— 一个优化像素似然、一个优化隐状态预测误差、一个优化符号一致性。如果一个分类桶里的成员没有共同的可证伪判据，那么「世界模型是关键部件」这一论断就无法被任何实验反驳。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>局限</strong>：本文（以及领域里的多数综述）把评测切成了与分类学同构的碎片 —— 感知有感知基准、规划有问答基准、控制有成功率基准。作者自己已经在第 8 节指出这不合理，但没有给出替代方案。</p><p><strong>新 framing</strong>：不要再问「这个模块好不好」，而是问「这个系统的错误发生在哪一层，以及某一层的改进有多少能兑现为端到端成功率」。可以借鉴软件工程与因果推断里的<strong>中介分析（mediation analysis）</strong>：把感知输出、规划输出、控制输出都视为可干预变量，在同一个长程任务上做 do 操作 —— 给定真值分割掩码（干预感知）、给定真值子任务序列（干预规划）、给定真值动作块（干预控制），分别测量端到端成功率的跃升。三个跃升幅度构成一张「兑现率表」，直接回答「现在最该投入哪一层」。</p><p><strong>相邻领域工具</strong>：这套做法在 NLP 的可解释性研究里已经成熟（activation patching / causal tracing），迁移到具身系统的障碍主要是需要一个能提供各层真值的仿真环境 —— 而这正是 ManiSkill3、AI2-THOR 这类平台天然具备的能力。</p><p><strong>第一个实验</strong>：在 <a href="/notes/papers/2410.00425">ManiSkill3</a> 的一组长程任务上，对一个现成的分层智能体（LLM 规划器 + 扩散策略）做三重干预，画出兑现率表。如果「给真值子任务序列」带来的跃升远小于「给真值动作块」，那么整个领域对高层规划的投入强度就需要重新校准；反之则说明控制层已经够用，瓶颈确实在大脑。这个结果无论朝哪个方向，都比再增加一份分类清单更有信息量。</p>',44)])])}const b=e(r,[["render",n]]);export{g as __pageData,b as default};
